{{--
    Browser tab / home-screen icon for the site and admin.
    Uses the favicon uploaded in Admin > SEO settings; falls back to the built-in BriefMedia mark,
    embedded inline so it works without copying any file to public_html.
--}}
@if(!empty($globalSeo?->favicon))
    <link rel="icon" type="image/png" href="{{ asset('storage/' . $globalSeo->favicon) }}">
    <link rel="apple-touch-icon" href="{{ asset('storage/' . $globalSeo->favicon) }}">
@else
    <link rel="icon" type="image/png" sizes="48x48" href="data:image/png;base64,">
@endif
<meta name="theme-color" content="#e4407f">
